/// Inverse dynamics torque `tau = M(q) qdd + C(q, qd) qd + g(q)`.
///
/// MIT-mode feed-forward torque for a desired joint acceleration.
///
/// `g_world` is the base-frame gravitational acceleration (e.g.
/// `[0.0, 0.0, -9.81]`). Named so it does not shadow [`gravity`].
pub fn inverse_dynamics(q: &[f64; 6], qd: &[f64; 6], qdd: &[f64; 6], g_world: &[f64; 3]) -> [f64; 6] {
    let m = mass_matrix(q);
    let c = coriolis(q, qd);
    let g = gravity(q, g_world);
    let mut tau = [0.0f64; 6];
    for i in 0..6 {
        let mut mqdd = 0.0;
        for j in 0..6 {
            mqdd += m[i][j] * qdd[j];
        }
        tau[i] = mqdd + c[i] + g[i];
    }
    tau
}
